def rearange_string(s):
    # Count the frequency of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if any character appears more than twice
    for count in char_count.values():
        if count > 2:
            return 'No'

    # Try to rearrange the string
    sorted_chars = sorted(char_count.items(), key=lambda x: x[1], reverse=True)
    result = ''
    i, j = 0, len(sorted_chars) - 1

    while i <= j:
        if i == j:
            result += sorted_chars[i][0]
        else:
            result += sorted_chars[i][0] + sorted_chars[j][0]
        i += 1
        j -= 1

    return result
