def common_prefix(strs, n):
    if not strs or n <= 0:
        return ""

    # Start with the first string as the initial prefix
    prefix = strs[0]

    # Iterate through each string starting from the second one
    for i in range(1, n):
        while strs[i].find(prefix) != 0:
            # Reduce the prefix by one character from the end until it matches the start of the current string
            prefix = prefix[:-1]

            # If the prefix becomes empty, there is no common prefix
            if not prefix:
                return ""

    return prefix
