def replace_max_specialchar(text, max_occurrences):
    # Define the characters to be replaced
    special_chars = [' ', ',', '.']

    # Initialize variables to keep track of the count of each character
    counts = {char: 0 for char in special_chars}

    # Count the occurrences of each character in the text
    for char in text:
        if char in special_chars:
            counts[char] += 1

    # Sort the characters by their occurrence count in descending order
    sorted_chars = sorted(special_chars, key=lambda x: counts[x], reverse=True)

    # Replace the maximum number of occurrences of the most frequent characters
    for _ in range(max_occurrences):
        for char in sorted_chars:
            if counts[char] > 0:
                text = text.replace(char, ':', 1)
                counts[char] -= 1

    return text
```

