        return arr[low]

    mid = (low + high) // 2

    # If middle element is greater than the last element,
    # then the minimum element must be in the right half.
    if arr[mid] > arr[high]:
        return find_Min(arr, mid+1, high)

    # Otherwise, the minimum element must be in the left half.
    return find_Min(arr, low, mid)
