def count_Primes_nums(n):
    if n <= 1:
        return 0
    primes = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (primes[p] == True):
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1
    count = 0
    for p in range(2, n):
        if primes[p]:
            count += 1
    return count
