def find_Element(arr, rotation_points, target_index, rotation_count):
    # Find the starting point of the array after rotations
    start = 0
    end = len(rotation_points) - 1

    while start <= end:
        mid = (start + end) // 2

        if rotation_points[mid][0] <= target_index < rotation_points[mid][1]:
            return arr[target_index]

        elif rotation_points[mid][0] > target_index:
            end = mid - 1

        else:
            start = mid + 1

    # If the target is not found within the rotated array
    return None
