def max_sum_increasing_subseq(arr, n, k, m):
    # Initialize dp array where dp[i] will store the maximum sum of increasing subsequence ending at arr[i]
    dp = [0] * (n + 1)

    # Iterate through each element in the array
    for i in range(1, n + 1):
        # Check all previous elements to find the longest increasing subsequence ending at arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    # Find the maximum sum of increasing subsequence ending at arr[k]
    max_sum = 0
    for i in range(k + 1, n + 1):
        max_sum = max(max_sum, dp[i])

    return max_sum
```

